import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function StudentDashboard() {
  const [activeTab, setActiveTab] = useState("VotingStatus");
  const [candidates, setCandidates] = useState([]);
  const [votingOpen, setVotingOpen] = useState(false);
  const [hasVoted, setHasVoted] = useState(false);
  const [message, setMessage] = useState("");
  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  // Fetch student dashboard data
  const fetchData = async () => {
    try {
      const [candidatesRes, votingRes] = await Promise.all([
        api.get("/candidates"),
        api.get("/student/voting-status"),
      ]);
      setCandidates(candidatesRes.data);
      setVotingOpen(votingRes.data.votingOpen);
      setHasVoted(votingRes.data.hasVoted);
    } catch (err) {
      console.error(err);
      if (err.response?.status === 401) {
        logout();
        navigate("/login");
      } else {
        setMessage(err.response?.data?.error || err.message);
      }
    }
  };

  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }
    fetchData();
  }, [token]);

  const voteForCandidate = async (id) => {
    if (!window.confirm("Are you sure you want to vote for this candidate?")) return;
    try {
      await api.post(`/student/vote/${id}`);
      setHasVoted(true);
      setMessage("Vote successfully submitted!");
    } catch (err) {
      console.error(err);
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Render content per tab ----------------
  const renderContent = () => {
    switch (activeTab) {
      case "VotingStatus":
        return (
          <Card title="Voting Status">
            <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>
              {votingOpen ? "Voting is OPEN" : "Voting is CLOSED"}
            </p>
            <p style={{ fontWeight: "bold", color: hasVoted ? "green" : "orange" }}>
              {hasVoted ? "You have voted ✅" : "You have not voted ❌"}
            </p>
          </Card>
        );
      case "Candidates":
        return (
          <Card title="Candidates">
            {candidates.length === 0 ? (
              <p style={{ color: "#777", fontStyle: "italic" }}>No candidates registered.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Position</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Party</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {candidates.map((c) => (
                    <tr key={c.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{c.name}</td>
                      <td style={{ padding: "8px" }}>{c.position}</td>
                      <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                      <td style={{ padding: "8px", textAlign: "center" }}>
                        <button
                          onClick={() => voteForCandidate(c.id)}
                          disabled={!votingOpen || hasVoted}
                          style={{
                            background: !votingOpen || hasVoted ? "#6c757d" : "#28a745",
                            color: "#fff",
                            border: "none",
                            borderRadius: "6px",
                            padding: "5px 10px",
                            cursor: !votingOpen || hasVoted ? "not-allowed" : "pointer",
                          }}
                        >
                          Vote
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );
      default:
        return null;
    }
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "Arial, sans-serif", backgroundColor: "#f4f6f8" }}>
      {/* Sidebar */}
      <aside
        style={{
          width: "220px",
          background: "#343a40",
          color: "#fff",
          paddingTop: "20px",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <nav style={{ display: "flex", flexDirection: "column", gap: "10px", paddingLeft: "20px" }}>
          <span
            style={{ cursor: "pointer", fontWeight: activeTab === "VotingStatus" ? "bold" : "normal" }}
            onClick={() => setActiveTab("VotingStatus")}
          >
            🏠 Voting Status
          </span>
          <span
            style={{ cursor: "pointer", fontWeight: activeTab === "Candidates" ? "bold" : "normal" }}
            onClick={() => setActiveTab("Candidates")}
          >
            👤 Candidates
          </span>
          <button
            onClick={() => {
              logout();
              navigate("/login");
            }}
            style={{
              marginTop: "auto",
              padding: "10px",
              borderRadius: "6px",
              border: "none",
              background: "#dc3545",
              color: "#fff",
              cursor: "pointer",
              fontWeight: "bold",
              marginLeft: "20px",
            }}
          >
            Logout
          </button>
        </nav>
      </aside>

      {/* Main Content */}
      <main style={{ flexGrow: 1, padding: "30px", maxWidth: "1000px", margin: "0 auto" }}>
        {renderContent()}
        {message && (
          <p
            style={{
              textAlign: "center",
              color: message.toLowerCase().includes("fail") ? "red" : "green",
              fontWeight: "bold",
              marginTop: "20px",
            }}
          >
            {message}
          </p>
        )}
      </main>
    </div>
  );
}
